import{_ as a,o as e,c as i,a3 as n}from"./chunks/framework.B7pF4b99.js";const k=JSON.parse('{"title":"01 · 開始使用","description":"","frontmatter":{},"headers":[],"relativePath":"topics/getting-started.md","filePath":"topics/getting-started.md","lastUpdated":1794275263000}'),t={name:"topics/getting-started.md"};function l(p,s,d,r,h,o){return e(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="_01-·-開始使用" tabindex="-1">01 · 開始使用 <a class="header-anchor" href="#_01-·-開始使用" aria-label="Permalink to &quot;01 · 開始使用&quot;">​</a></h1><p>本章的目標是從 PowerShell 啟動 WUWAOS，分清楚主機、模擬器與客體作業系統。</p><h2 id="三個執行環境" tabindex="-1">三個執行環境 <a class="header-anchor" href="#三個執行環境" aria-label="Permalink to &quot;三個執行環境&quot;">​</a></h2><table tabindex="0"><thead><tr><th>環境</th><th>負責什麼</th></tr></thead><tbody><tr><td>Windows／PowerShell</td><td>你輸入啟動指令的主機</td></tr><tr><td>Windows portable 環境或 WSL Ubuntu</td><td>用 Clang、LLD、Make 建置 RISC-V 程式，執行 QEMU</td></tr><tr><td>QEMU 裡的 WUWAOS</td><td>核心管理虛擬硬體，使用者 shell 接受 OS 指令</td></tr></tbody></table><p>QEMU 的 virt 機型提供的是指定的虛擬硬體。WUWAOS 仍須有對應驅動與核心機制才能使用裝置。</p><h2 id="建置與啟動" tabindex="-1">建置與啟動 <a class="header-anchor" href="#建置與啟動" aria-label="Permalink to &quot;建置與啟動&quot;">​</a></h2><h3 id="目前原始碼的-cli-磁碟開機" tabindex="-1">目前原始碼的 CLI 磁碟開機 <a class="header-anchor" href="#目前原始碼的-cli-磁碟開機" aria-label="Permalink to &quot;目前原始碼的 CLI 磁碟開機&quot;">​</a></h3><p>WSL Ubuntu 需備有 Clang、LLD、llvm-objcopy、Make、Python 3、QEMU RISC-V 與 OpenSBI。從 PowerShell 進入你的專案目錄，再啟動 QEMU。</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd C:\\programing\\WUWAOS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wsl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d Ubuntu </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> make run</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">disk</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>這條指令在 WSL 交叉編譯，將核心安裝到 <code>build/wuwaos-cli.img</code>。QEMU 啟動 OpenSBI 後，flash 裡的載入器從磁碟讀取 <code>/boot/kernel.elf</code>，同一個 PowerShell 視窗最後會顯示 <code>wuwaos/&gt;</code>。實際交接順序見<a href="./boot.html">開機流程</a>。</p><p>此路徑使用一顆 WUFS0002 磁碟，停用 swap，並要求 journal 無待重播紀錄。<code>make clean</code> 保留磁碟與裡面的檔案。需要用 QEMU 直接載入核心並附加獨立 swap 磁碟時，可執行 <code>wsl -d Ubuntu -- make run</code>，它使用 <code>build/wuwaos.img</code> 與 <code>build/wuwaos-swap.img</code>。若要重播待處理的 journal，請使用跳過主機映像更新的<a href="./../SPEC-32-wufs-redo-journal.html#新磁碟與-pending-recovery-操作">復原流程</a>。</p><h3 id="windows-免安裝版本" tabindex="-1">Windows 免安裝版本 <a class="header-anchor" href="#windows-免安裝版本" aria-label="Permalink to &quot;Windows 免安裝版本&quot;">​</a></h3><p>下載 <a href="https://github.com/johnson931128/WUWAOS/releases/tag/portable-windows-v1" target="_blank" rel="noreferrer">Windows portable v1 Release</a> 的完整 ZIP 並解壓，環境就已準備完成。下載與校驗指令見 <a href="./../portable-windows.html">Windows portable 指南</a>。在專案根目錄的 PowerShell 執行：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Start-WUWAOS.cmd</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 自動編譯並進入 CLI</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Start-WUWAOS.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> gui   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 自動編譯並開啟圖形桌面</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Start-WUWAOS.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> build </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 編譯並準備磁碟映像，不啟動 QEMU</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>需要操作 Makefile 時，可先用 <code>.\\Start-WUWAOS.cmd shell</code> 進入隨附環境，再輸入 <code>make</code>、<code>make run</code> 或 <code>make run-gui GUI_DISPLAY=gtk</code>。一般啟動不必手動設定 Bash 路徑或環境變數。</p><p><strong>目前原始碼搭配 portable 工具環境</strong>也支援磁碟開機。在 PowerShell 執行：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Start-WUWAOS.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> shell</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>進入 Bash 後輸入：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run-disk</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>這會使用 <code>build/boot-flash.img</code> 的載入器，從 <code>build/wuwaos-cli.img</code> 讀取 <code>/boot/kernel.elf</code>；完整 ASCII 圖解見<a href="./boot.html#磁碟開機-主機先準備什麼">磁碟開機原理</a>。原始 portable v1 ZIP 使用該版本內的直接開機流程，須有目前原始碼才有 <code>run-disk</code> target。</p><h3 id="最新原始碼的磁碟保護與檢查" tabindex="-1">最新原始碼的磁碟保護與檢查 <a class="header-anchor" href="#最新原始碼的磁碟保護與檢查" aria-label="Permalink to &quot;最新原始碼的磁碟保護與檢查&quot;">​</a></h3><p>目前原始碼在 kernel 與主機映像工具都加入非空白磁碟保護：magic 不符時，只有確認全部資料為零才允許初始化。一般啟動前會維護磁碟映像；要驗證 kernel 的空白／損毀處理，請使用固定測試入口：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Test-FsDisk.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> valid</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Test-FsDisk.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> blank</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Test-FsDisk.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> damaged</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Test-FsDisk.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tail</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>每次都會自動編譯並建立獨立測試磁碟。按 Ctrl+A，放開後按 X 結束 QEMU，工具才會檢查前後雜湊。預期訊息與結果見 <a href="./../SPEC-31-filesystem-initialization-guard.html">Spec 31</a>。這些是 portable v1 之後的原始碼更新；v1 ZIP 沒有上述測試入口，也不包含本次保護修正。使用者已確認磁碟保護驗證完成，證據範圍與未驗證項目記錄於該規格。</p><h2 id="進入系統後" tabindex="-1">進入系統後 <a class="header-anchor" href="#進入系統後" aria-label="Permalink to &quot;進入系統後&quot;">​</a></h2><p>看到開機動畫和 <code>wuwaos/&gt;</code> 後，以下指令才是在 WUWAOS 裡輸入：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>help</span></span>
<span class="line"><span>ps</span></span>
<span class="line"><span>vmstat</span></span>
<span class="line"><span>ls /</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>應能看到可用命令、行程資訊、分頁統計與根目錄。使用 <code>fan /home/user/note.txt</code> 可以進入編輯器；詳見<a href="./applications.html">使用者程式</a>。</p><p>按 <code>Ctrl+A</code>，放開後按 <code>X</code> 離開 QEMU。<code>exit</code> 只結束 shell，並不關閉虛擬電腦。</p><h2 id="對應程式碼" tabindex="-1">對應程式碼 <a class="header-anchor" href="#對應程式碼" aria-label="Permalink to &quot;對應程式碼&quot;">​</a></h2><p><code>Makefile</code> 負責交叉編譯、連結與 QEMU 參數；<code>tools/make_disk.py</code> 維護 WUFS 映像；<code>tools/make_swap.py</code> 建立專用交換區。它們是在主機執行的工具，不是 WUWAOS 的 syscall（系統呼叫）。</p><h2 id="閱讀與驗證邊界" tabindex="-1">閱讀與驗證邊界 <a class="header-anchor" href="#閱讀與驗證邊界" aria-label="Permalink to &quot;閱讀與驗證邊界&quot;">​</a></h2><p>本機文件網站是另一個主機程式，不在 QEMU 裡執行。其啟動方式見<a href="./writing.html">維護文件網站</a>。OS 既有操作與結果見<a href="./../history.html">規格紀錄</a>，本次文件建置不會重新驗證核心功能。</p><p>觀念參考：<code>notes/ch1 Introduction.md</code>、<code>notes/ch2 Operating-System Structures.md</code>。本章指令則依 WUWAOS 的 Makefile 與操作介面整理。</p>`,34)])])}const b=a(t,[["render",l]]);export{k as __pageData,b as default};
